import { hexDistance } from "./hex.js";
import { getActivationEnvelope, interpolate, smootherstep } from "./motion.js";
function clamp(value, min = 0, max = 1) {
    return Math.min(max, Math.max(min, value));
}
function hashString(input) {
    let hash = 2166136261;
    for (let i = 0; i < input.length; i += 1) {
        hash ^= input.charCodeAt(i);
        hash = Math.imul(hash, 16777619);
    }
    return hash >>> 0;
}
function seededValue(seed, value) {
    return hashString(`${seed ?? "topology"}:${value}`) / 4294967295;
}
function stateForIntensity(state, intensity, id, type) {
    return {
        id,
        state,
        intensity: clamp(intensity, 0, 1),
        ...(type ? { type } : {}),
    };
}
export function toGridCellStateMap(states) {
    return Object.fromEntries(states.map((state) => [state.id, state]));
}
export function getCenterBloomFrame(options) {
    const { cells, origin, frame, maxRadius, trail = 2, wrap = true } = options;
    const cycle = Math.max(1, maxRadius + trail + 1);
    const position = wrap ? ((frame % cycle) + cycle) % cycle : Math.max(0, frame);
    const attack = 0.72;
    return cells.map((cell) => {
        const distance = hexDistance(origin, cell);
        const offset = position - distance;
        const intensity = getActivationEnvelope(offset, {
            attack,
            hold: 0.08,
            release: trail + 0.8,
        });
        if (intensity <= 0.015) {
            return stateForIntensity("idle", offset < 0 ? 0.18 : 0.12, cell.id);
        }
        if (offset >= -attack && offset <= 0.36) {
            return stateForIntensity("active", intensity, cell.id);
        }
        return stateForIntensity("trail", Math.max(0.12, intensity * 0.82), cell.id);
    });
}
export function getDiagonalSweepFrame(options) {
    const { cells, frame, width, trail = 3, wrap = true } = options;
    const bands = cells.map((cell) => cell.q + cell.r);
    const minBand = Math.min(...bands);
    const maxBand = Math.max(...bands);
    const totalBands = Math.max(1, maxBand - minBand + 1);
    const span = Math.max(1, width ?? totalBands);
    const position = wrap ? ((frame % span) + span) % span : Math.max(0, frame);
    const currentBand = minBand + position;
    const attack = 0.68;
    return cells.map((cell) => {
        const band = cell.q + cell.r;
        const offset = currentBand - band;
        const intensity = getActivationEnvelope(offset, {
            attack,
            hold: 0.05,
            release: trail + 0.8,
        });
        if (intensity <= 0.015) {
            return stateForIntensity("idle", offset < 0 ? 0.14 : 0.1, cell.id);
        }
        if (offset >= -attack && offset <= 0.34) {
            return stateForIntensity("active", intensity, cell.id);
        }
        return stateForIntensity("trail", Math.max(0.1, intensity * 0.78), cell.id);
    });
}
export function getDiagonalToneSweepFrame(options) {
    const { cells, frame, width, trail = 3, wrap = true } = options;
    const bands = cells.map((cell) => cell.q + cell.r);
    const minBand = Math.min(...bands);
    const maxBand = Math.max(...bands);
    const totalBands = Math.max(1, maxBand - minBand + 1);
    const span = Math.max(1, width ?? totalBands);
    const position = wrap ? ((frame % span) + span) % span : Math.max(0, frame);
    const currentBand = minBand + position;
    const attack = 0.72;
    return cells.map((cell) => {
        const band = cell.q + cell.r;
        const offset = currentBand - band;
        const intensity = getActivationEnvelope(offset, {
            attack,
            hold: 0.08,
            release: trail + 1,
        });
        const toneIntensity = clamp(0.08 + intensity * 0.72, 0.08, 1);
        if (intensity <= 0.015) {
            return stateForIntensity("idle", toneIntensity * 0.52, cell.id, "diagonal-tone-sweep");
        }
        return stateForIntensity("converted", toneIntensity, cell.id, "diagonal-tone-sweep");
    });
}
export function getMoodConversionFrame(options) {
    const { cells, progress, seed } = options;
    const normalizedProgress = clamp(progress, 0, 1);
    const fadeWidth = 0.12;
    return cells.map((cell) => {
        const threshold = seededValue(seed, cell.id);
        const idleIntensity = 0.16 + threshold * 0.16;
        if (normalizedProgress >= threshold) {
            const fadeEnd = Math.min(1, threshold + fadeWidth);
            const localProgress = smootherstep(threshold, fadeEnd, normalizedProgress);
            return stateForIntensity("converted", interpolate(idleIntensity, 1, localProgress), cell.id);
        }
        return stateForIntensity("idle", idleIntensity, cell.id);
    });
}
function coordinateKey(coordinate) {
    return `${coordinate.q}:${coordinate.r}`;
}
export function selectGridActivityCell({ cells, occupied = [], previous = null, fallback = null, minDistance = 5, minEdgeFactor = 0.5, random = Math.random, }) {
    const occupiedIds = new Set(occupied.map(coordinateKey));
    const eligible = cells.filter((cell) => (!occupiedIds.has(coordinateKey(cell))
        && (cell.edgeFactor ?? 1) >= minEdgeFactor));
    if (!eligible.length)
        return fallback;
    const distant = previous
        ? eligible.filter((cell) => hexDistance(cell, previous) >= minDistance)
        : eligible;
    const pool = distant.length ? distant : eligible;
    const randomValue = Math.min(0.999999, Math.max(0, random()));
    return pool[Math.floor(randomValue * pool.length)] ?? pool[0] ?? fallback;
}
